import { test, expect } from '@playwright/test';

test.describe('Dark Mode Toggle from User Preferences', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/settings');
  });

  test('should successfully toggle dark mode from user preferences', async ({ page }) => {
    // Verify dark mode is initially off (light mode)
    const body = page.locator('body');
    await expect(body).toHaveClass(/light-mode/);
    const toggleButton = page.getByRole('button', { name: /toggle dark mode/i });
    await expect(toggleButton).toBeVisible();

    // Click toggle button to enable dark mode
    await toggleButton.click();

    // Verify dark mode is now active
    await expect(body).toHaveClass(/dark-mode/);
    const toggleButtonAfter = page.getByRole('button', { name: /toggle dark mode/i });
    await expect(toggleButtonAfter).toBeVisible();

    // Verify dark mode toggle button text has updated
    await expect(toggleButtonAfter).toContainText('Switch to light mode');

    // Verify dark mode class is present
    await expect(body).toHaveClass(/dark-mode/);

    // Click toggle button again to disable dark mode
    await toggleButtonAfter.click();

    // Verify dark mode is disabled
    await expect(body).not.toHaveClass(/dark-mode/);
    await expect(body).toHaveClass(/light-mode/);

    // Verify toggle button text has reverted
    await expect(toggleButtonAfter).toContainText('Toggle dark mode');
  });

  test('should handle dark mode toggle when preferences are disabled', async ({ page }) => {
    // Navigate to preferences section
    await page.getByRole('link', { name: /preferences/i }).click();
    await page.waitForURL(/.*preferences/);

    // Verify dark mode toggle is visible
    const toggleButton = page.getByRole('button', { name: /toggle dark mode/i });
    await expect(toggleButton).toBeVisible();

    // Disable dark mode preference
    const darkModeOption = page.getByLabel(/dark mode/i);
    await expect(darkModeOption).toBeVisible();
    await darkModeOption.click();

    // Verify preference is disabled
    await expect(darkModeOption).toContainText('Disabled');

    // Verify dark mode toggle button is disabled and shows disabled state
    await expect(toggleButton).toBeDisabled();
    await expect(toggleButton).toContainText('Disabled');

    // Verify dark mode class is not applied to body
    const body = page.locator('body');
    await expect(body).not.toHaveClass(/dark-mode/);

    // Verify light mode class is applied
    await expect(body).toHaveClass(/light-mode/);

    // Attempt to click disabled toggle button
    await expect(toggleButton).toBeDisabled();
    await expect(toggleButton).not.toBeEnabled();
  });
});
